package com.microbms.gateway;
import org.springframework.boot.web.reactive.error.ErrorWebExceptionHandler; import org.springframework.core.Ordered; import org.springframework.core.annotation.Order; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import java.nio.charset.StandardCharsets; import java.net.ConnectException;
@Component @Order(Ordered.HIGHEST_PRECEDENCE) public class DownstreamErrorHandler implements ErrorWebExceptionHandler {
 @Override public Mono<Void> handle(ServerWebExchange exchange,Throwable ex){Throwable cause=ex;while(cause.getCause()!=null)cause=cause.getCause();if(!(cause instanceof ConnectException)&&!ex.getClass().getName().contains("ConnectException"))return Mono.error(ex);exchange.getResponse().setStatusCode(HttpStatus.SERVICE_UNAVAILABLE);exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);byte[] body="{\"error\":\"service_unavailable\",\"message\":\"A required service is temporarily unavailable. Please try again.\"}".getBytes(StandardCharsets.UTF_8);return exchange.getResponse().writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(body)));}
}
